function Svg({ vb, paths, className, title }: P & { vb: string; paths: [string, string][] }) {
  return (
    <svg viewBox={vb} className={className} role={title ? 'img' : undefined} aria-label={title} aria-hidden={title ? undefined : true} fill="currentColor">
      {paths.map(([rule, d], i) => <path key={i} fillRule={rule as 'nonzero' | 'evenodd'} d={d} />)}
    </svg>
  )
}

